window.GLYPHS = {"ERAS":["甲骨","金文","小篆","隶书","简体"],"STORIES":[{"id":"ri","glyph":"日","meaning":"太阳","motion":"sun","texts":["夜色里，刻字的人抬头看太阳。刀刻不出圆，他索性用方框困住了光。","到了青铜时代，太阳重新变圆。正中的一点，像一颗不肯熄灭的火种。","王朝需要统一。圆被拉成长框，野生的太阳第一次服从秩序。","毛笔落下，圆彻底变方。光不再高悬天上，而是进入每个人的书页。","今天的「日」只有四画。可日历、日期、每日——我们的时间，仍由它点亮。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 日-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 日-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 日-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"16\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M58 88 Q150 72 242 88\"/>\n      <path d=\"M70 92 V208\"/>\n      <path d=\"M230 92 V208\"/>\n      <path d=\"M70 148 Q150 136 230 148\"/>\n      <path d=\"M58 212 Q150 228 242 212\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">日</text>"}],"hook":"太阳第一次被写下，竟然不是圆的。","payoff":"三千年后，我们仍从这一格光开始。"},{"id":"yue","glyph":"月","meaning":"月亮","motion":"moon","texts":["三千年前的夜里，有人画下一弯缺月。两道短痕，是月面，也是未说完的心事。","月亮被铸进青铜，弧线变得厚重。它开始照见祭祀，也照见等待归来的人。","小篆把月拉得修长。古人说月是“太阴之精”——它靠残缺，标记完整时间。","隶书把弯月拉直，像一扇半开的门。门外是夜，门内是人的思念。","今天的「月」仍没有圆满。可正因为阴晴圆缺，我们才学会等待。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 月-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 月-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 月-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"16\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M92 70 Q78 150 98 240\"/>\n      <path d=\"M92 70 Q168 78 186 118 Q196 168 168 236 Q150 252 118 246\"/>\n      <path d=\"M108 128 Q148 136 160 148\"/>\n      <path d=\"M108 176 Q148 184 158 196\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">月</text>"}],"hook":"古人写月亮时，为什么故意留下缺口？","payoff":"因为月亮最动人的，从来不是圆满。"},{"id":"shan","glyph":"山","meaning":"山岳","motion":"mountain","texts":["地平线上，三座峰突然升起。中峰最高——甲骨文的山，就是一次真实的远眺。","山被铸入青铜，峰谷变得浑厚。人们把不可撼动的力量，带进庙堂。","小篆开始修整群峰。自然的锋芒，被收进对称与秩序。","隶变像一场削山工程：曲线断开，三座峰变成三根挺立的竖线。","今天的「山」只有三竖一折。字很小，却仍让每个看见它的人抬头。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 山-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 山-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 山-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"16\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M78 92 V214\"/>\n      <path d=\"M150 58 V214\"/>\n      <path d=\"M222 92 V214\"/>\n      <path d=\"M52 220 Q150 232 248 220\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">山</text>"}],"hook":"三座真正的山峰，最后只剩三根竖线。","payoff":"山被写小了，人的仰望没有。"},{"id":"shui","glyph":"水","meaning":"流水","motion":"water","texts":["一条主流向前，两边的支流追赶。甲骨文的水，不是图案，是正在发生的流动。","青铜让水流变得厚重，可每一道弯曲仍在寻找出口。","小篆竖起中轴，让四道水波围绕它转身。自由第一次遇见规则。","隶书把波浪切成点画。看似安静，笔势却仍向四面溅开。","今天的「水」静静写在纸上。只要落笔，它就会再次流起来。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 水-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 水-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 水-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"15\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M150 52 V214\"/>\n      <path d=\"M78 108 Q128 138 82 178\"/>\n      <path d=\"M222 108 Q172 138 218 178\"/>\n      <path d=\"M96 214 Q150 246 204 214\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">水</text>"}],"hook":"水没有固定形状，却最早拥有了自己的字。","payoff":"它改变了形状，从未停止流动。"},{"id":"ren","glyph":"人","meaning":"人","motion":"walk","texts":["他侧身站在三千年前：有头、有手、有脚。甲骨文留下了人类最早的自画像。","青铜时代，他站得更稳。人不再只是肉身，也成为宗族与责任。","小篆慢慢省去头脸，只留下弯腰前行的姿态——人，开始成为所有人。","隶书挥出一撇一捺。两条腿分开，像下一秒就要走出画面。","今天的「人」只有两笔。一笔独立，一笔支撑：没有谁真正只靠自己站立。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 人-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 人-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 人-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"17\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M168 62 Q120 128 58 236\"/>\n      <path d=\"M128 118 Q186 150 248 238\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">人</text>"}],"hook":"“人”的第一张照片，只有一个孤独的侧影。","payoff":"两笔撑住的，是无数种人生。"},{"id":"mu","glyph":"木","meaning":"树木","motion":"tree","texts":["枝向天空，根扎土地，中间是一条脊梁。甲骨文画下的，是一棵活着的树。","到了青铜时代，枝根向外张开。它既是生命，也是房屋、舟车和火。","小篆让枝、干、根彼此对称。野树被修成文明可以理解的形状。","隶书横平竖直，木开始像一件可以丈量、切割、建造的材料。","今天的「木」只有四画。加一棵成林，加屋顶成宋——文明仍在它的枝头生长。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 木-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 木-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 木-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"16\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M150 48 V220\"/>\n      <path d=\"M52 138 Q150 124 248 138\"/>\n      <path d=\"M96 220 Q150 176 204 220\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">木</text>"}],"hook":"一棵树，怎样长成整座文明？","payoff":"树被写进字里，也写进了我们的生活。"},{"id":"huo","glyph":"火","meaning":"火焰","motion":"fire","texts":["黑夜中央，火焰突然站起。两旁的火星飞散——这是先民最危险也最迷人的伙伴。","火被铸进青铜，焰形稳定下来。它能煮熟食物，也能把祈愿送向天空。","小篆让火焰向上聚拢。狂野的燃烧，开始拥有可以传承的轮廓。","隶变猛地劈开撇捺，四点飞向两侧。火最剧烈的一瞬，被定格成字。","今天的「火」依然张开四肢。每次写下它，纸面都像突然亮了一度。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 火-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 火-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 火-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"15\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M78 118 Q118 150 108 186\"/>\n      <path d=\"M222 118 Q182 150 192 186\"/>\n      <path d=\"M150 62 Q118 150 92 236\"/>\n      <path d=\"M150 62 Q198 158 230 238\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">火</text>"}],"hook":"人类驯服火之前，先把它画了下来。","payoff":"火照亮了夜，也改变了人。"},{"id":"yu","glyph":"雨","meaning":"雨水","motion":"rain","texts":["云压下来，雨滴成排坠落。甲骨上的这一场雨，曾决定收成与生死。","青铜把云盖铸得更厚，雨点落得更整齐。天空像在发布一道命令。","小篆给雨造了一间屋：上面是天，里面是云，四点是奔向土地的水。","隶书把风暴收进方框。越是整齐，越能听见框内密集的雨声。","今天的「雨」几乎没有改变。三千年前落下的那一场，仍在这个字里回响。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 雨-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 雨-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 雨-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M48 78 Q150 64 252 78\"/>\n      <path d=\"M86 86 V138 H214 V86\"/>\n      <path d=\"M118 162 V238\"/>\n      <path d=\"M150 154 V246\"/>\n      <path d=\"M182 162 V238\"/>\n      <path d=\"M108 186 H128 M140 178 H160 M172 186 H192\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">雨</text>"}],"hook":"三千年前的一场雨，为什么至今还没停？","payoff":"因为人类第一次，把天气写成了记忆。"},{"id":"ma","glyph":"马","meaning":"马","motion":"gallop","texts":["鬃毛扬起，四蹄腾空，尾巴甩向身后。甲骨文把一匹马按在了奔跑的瞬间。","青铜时代，马变得更强壮。它带来速度，也改变战争与疆域。","小篆让马站直，鬃、目、身与足被收进纵向结构。奔跑第一次被压进秩序。","隶书写成「馬」。四点仍在字底，像落地前一秒悬空的蹄。","今天的「马」只剩三画。可当最后一横甩出，三千年的风仍从耳边掠过。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 馬-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 馬-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 馬-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M118 52 Q96 78 108 118 Q120 148 150 158 Q186 148 196 112 Q204 74 176 54 Q148 46 118 52 Z\"/>\n      <path d=\"M128 88 H176 M128 118 H176\"/>\n      <path d=\"M150 158 V188\"/>\n      <path d=\"M72 196 Q150 184 228 196\"/>\n      <path d=\"M96 196 Q90 236 78 258\"/>\n      <path d=\"M128 196 Q128 236 122 258\"/>\n      <path d=\"M172 196 Q176 236 182 258\"/>\n      <path d=\"M204 196 Q214 236 226 258\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">马</text>"}],"hook":"这个字里，曾经真的有四条腿。","payoff":"笔画越来越少，蹄声从未远去。"},{"id":"yu-fish","glyph":"鱼","meaning":"鱼","motion":"swim","texts":["鱼头、鱼鳞、鱼鳍、鱼尾，一样不少。甲骨文把水里的生命完整捞上岸。","青铜上的鱼更圆、更重，鳞片排成队。它是食物，也是丰收的愿望。","小篆让鱼突然直立。它离开真实姿态，开始学习成为一个符号。","隶书写成「魚」，底下四点既像尾鳍，也像刚刚甩落的水珠。","今天的「鱼」游进八画之中。身体被简化，摆尾的方向却从未改变。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 魚-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 魚-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 魚-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M150 46 Q108 58 100 118 V188 Q108 236 150 252 Q192 236 200 188 V118 Q192 58 150 46 Z\"/>\n      <path d=\"M118 102 H182 M118 136 H182 M118 170 H182\"/>\n      <path d=\"M100 198 Q78 228 70 246\"/>\n      <path d=\"M200 198 Q222 228 230 246\"/>\n      <path d=\"M118 246 Q150 272 182 246\"/>\n      <path d=\"M132 250 Q150 262 168 250\"/>\n      <path d=\"M118 258 Q150 278 182 258\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">鱼</text>"}],"hook":"一条鱼游了三千年，最后游进了八画里。","payoff":"形状会被时间带走，生命感不会。"},{"id":"che","glyph":"车","meaning":"车","motion":"cart","texts":["两只车轮、一根长轴、中间是车厢。甲骨文像从天空拍下第一辆战车。","青铜上的轮辐更加清楚。车让距离缩短，也让战争突然加速。","小篆把圆轮收进中轴。真实机器，被折叠成一套精密结构。","隶书写成「車」，方框像车厢，长横像道路，车轮藏进了笔画。","今天的「车」只剩四画。轮子消失了，向前的力量却留了下来。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 車-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 車-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 車-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M58 78 Q150 64 242 78\"/>\n      <path d=\"M150 78 V226\"/>\n      <path d=\"M72 148 Q150 136 228 148\"/>\n      <path d=\"M108 108 H192 V188 H108 Z\"/>\n      <path d=\"M58 226 Q150 240 242 226\"/>\n      <path d=\"M108 226 V258 M150 226 V262 M192 226 V258\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">车</text>"}],"hook":"第一辆车，竟然是从天空俯拍的。","payoff":"轮子被简化了，人仍在向前。"},{"id":"jia","glyph":"家","meaning":"家","motion":"home","texts":["屋顶下面，一头猪安静卧着。对先民来说，有房、有畜、有食物，才敢称为家。","青铜时代，屋檐张得更开。被遮蔽的不只是牲畜，也是一个家族的未来。","小篆把屋顶写成「宀」，把猪藏进笔画。生活现场开始变成抽象概念。","隶书让「家」彻底定型。那头猪看不见了，可“养”的含义没有消失。","今天我们写下「家」，想到的早已不是牲畜。可家的本质仍是：有人等你回来。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 家-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 家-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 家-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M48 108 L150 46 L252 108\"/>\n      <path d=\"M78 108 V136 H222 V108\"/>\n      <path d=\"M150 152 Q118 156 114 198 Q118 236 150 250 Q182 236 186 198 Q182 156 150 152 Z\"/>\n      <path d=\"M128 186 H172 M124 214 H176\"/>\n      <path d=\"M186 188 L232 168\"/>\n      <path d=\"M124 246 L108 276 M150 250 V278 M176 246 L192 276\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">家</text>"}],"hook":"为什么“家”的屋顶下，住着一头猪？","payoff":"家不是房子，是被照料的生命。"},{"id":"ming","glyph":"明","meaning":"明","motion":"glow","texts":["最早的「明」，可能是一扇窗迎着月光。黑夜没有退场，人先打开了一道缝。","到了青铜时代，左边渐成太阳，右边仍是缺月。昼与夜第一次站在一起。","小篆正式写成日月并列。两种完全相反的光，共同解释“看见”。","隶书把日月拉开，像两个人各自站稳，却把光投向同一个地方。","今天的「明」仍由日月组成。真正的明亮，也许从来不是只有一种声音。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 明-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 明-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 明-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M48 82 Q92 70 132 82\"/>\n      <path d=\"M56 86 V214\"/>\n      <path d=\"M124 86 V214\"/>\n      <path d=\"M56 148 Q92 138 124 148\"/>\n      <path d=\"M48 218 Q92 230 132 218\"/>\n      <path d=\"M176 70 Q158 150 178 238\"/>\n      <path d=\"M176 70 Q232 84 242 128 Q248 176 222 232 Q204 250 184 244\"/>\n      <path d=\"M188 128 Q224 138 232 150\"/>\n      <path d=\"M188 176 Q220 186 228 198\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">明</text>"}],"hook":"太阳和月亮，真的组成了“明”吗？","payoff":"光不是一个答案，而是两个世界相遇。"},{"id":"dong","glyph":"东","meaning":"东","motion":"dawn","texts":["甲骨文画的是一只两端扎紧的口袋。它和日出无关，却被时间推向东方。","青铜时代，绳结与囊身仍清晰可见。这个字还没决定自己未来的意义。","小篆出现了浪漫的新解释：太阳卡在树中，东方于是成为光升起的地方。","隶书写成「東」。树与太阳牢牢嵌合，后来的故事覆盖了最初的真相。","今天的「东」只剩五画。文字最迷人的地方是：误读，也可能活成新的真实。"],"forms":[{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 東-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 東-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/webp;base64,","source":"Wikimedia Ancient Chinese Characters · 東-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"\n    <g fill=\"none\" stroke=\"#e6dfd0\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"14\" transform=\"translate(0,18) scale(1.14,0.78) translate(-18,42)\">\n      <path d=\"M150 46 V226\"/>\n      <path d=\"M58 148 Q150 134 242 148\"/>\n      <path d=\"M96 226 Q150 178 204 226\"/>\n      <path d=\"M96 72 H204 V128 H96 Z\"/>\n      <path d=\"M110 96 H190\"/>\n    </g>\n  "},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">东</text>"}],"hook":"“东”最初可能根本不是太阳升起。","payoff":"一个误读，也能长成整个方向。"},{"id":"long","glyph":"龙","meaning":"龙","motion":"dragon","hook":"龙最初不是神话，而是一条被刻进骨头的巨兽。","payoff":"鳞爪被笔画收走，腾跃的力量留了下来。","texts":["甲骨文的龙弓身卷尾，头上有角，巨口向前。先民把敬畏刻成一只有形的兽。","金文让龙身更加盘曲，角、爪与鳞甲纠缠在青铜光泽里，它开始靠近神灵。","小篆把飞动的躯体收进纵向结构，曲线仍像云中翻转的脊梁。","隶书写成「龍」，龙首、龙身和尾部被压进密集笔画，野性开始服从书写。","今天的「龙」只剩五画。形体被极度压缩，昂首腾空的方向没有改变。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龍-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龍-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龍-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">龍</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">龙</text>"}]},{"id":"niao","glyph":"鸟","meaning":"飞鸟","motion":"fly","hook":"这个字里，曾完整地藏着一只回头的鸟。","payoff":"羽毛一笔笔消失，飞翔没有。","texts":["甲骨文画出鸟喙、眼睛、翅膀、足与长尾，像一只刚刚落上树枝的鸟。","金文的羽翼更加丰满，尾羽向后舒展，青铜把轻盈变成了重量。","小篆让鸟直立起来，头、身和尾被组织成一条适合书写的轴线。","隶书写成「鳥」，底下四点像收拢的爪，也像振翅时落下的羽毛。","今天的「鸟」只有五画。尾羽变成一横，它仍随最后一点飞出纸面。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 鳥-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 鳥-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 鳥-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">鳥</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">鸟</text>"}]},{"id":"gui","glyph":"龟","meaning":"龟","motion":"crawl","hook":"甲骨文的甲骨，竟把自己的主人也画了进去。","payoff":"龟甲保存文字，文字也保存了龟。","texts":["甲骨文从侧面画龟：头颈伸出，背甲隆起，四足和短尾贴近地面。","金文把龟甲刻得更厚，甲纹与肢体仍然清楚，缓慢因此有了分量。","小篆把头、甲、足、尾折进修长结构，真实的龟开始蜕变为复杂符号。","隶书写成「龜」，密集折画像层层甲片，古老生命被封存在字的内部。","今天的「龟」轻了许多。外壳被简化，缓慢而坚定的脚步仍在向前。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龜-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龜-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 龜-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">龜</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">龟</text>"}]},{"id":"zhou","glyph":"舟","meaning":"舟船","motion":"sail","hook":"第一只舟，是一段被掏空的树干。","payoff":"船形变成六画，人类继续越过水面。","texts":["甲骨文像俯视一只独木舟：两端上翘，中间空出船舱，水路由此被打开。","金文加深船舷与舱格，舟不只是工具，也载着贡物、军队与远方。","小篆将船身竖起，弧形船舷被拉成长轴，水上的横物变成纸上的竖字。","隶书舒展横画，舟体渐平方正，摇晃的船开始服从稳定的笔势。","今天的「舟」仍像一叶船。六画之间，留着可以容纳远方的空处。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 舟-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 舟-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 舟-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">舟</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">舟</text>"}]},{"id":"hu-tiger","glyph":"虎","meaning":"猛虎","motion":"prowl","hook":"虎的斑纹，曾经就是这个字的一部分。","payoff":"皮毛被抽象成笔画，扑出的力量仍伏在其中。","texts":["甲骨文画出张口的虎头、长身、利爪和卷尾，斑纹沿着背部起伏。","金文让虎身更厚重，爪牙与尾巴仍在，威严被铸进祭器。","小篆把虎头收成「虍」，身体蜷在下方，猛兽第一次进入字形的笼子。","隶书拉开撇横，虎的躯干被拆成笔画，仍保持向前压低的姿态。","今天的「虎」有八画。最后一弯像尾巴扫过，字面仍藏着一次扑击。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 虎-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 虎-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 虎-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">虎</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">虎</text>"}]},{"id":"xiang","glyph":"象","meaning":"大象","motion":"elephant","hook":"中原曾有象群，所以先民能画下真正的大象。","payoff":"象离开了北方，却留在想象与万象之中。","texts":["甲骨文画出长鼻、大耳、粗身与四足，一头真实的大象站在三千年前。","金文让象身更加圆厚，长鼻向下弯曲，它既是猛兽，也是王权的奇观。","小篆把头、鼻、身、足纵向叠合，庞然巨物被收进一枚修长的字。","隶书把弧线变成撇捺，象的四足藏入下部，长鼻仍从上方向前伸出。","今天的「象」有十一画。我们用它表示形象、现象，因为看见从它开始。"],"forms":[{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 象-oracle.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 象-bronze.svg · CUHK / Academia Sinica cross-check"},{"asset":"data:image/png;base64,","source":"Wikimedia Ancient Chinese Characters · 象-seal.svg · CUHK / Academia Sinica cross-check"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">象</text>"},{"viewBox":"0 0 300 300","body":"<text x=\"150\" y=\"215\" text-anchor=\"middle\" font-family=\"Noto Serif SC, serif\" font-size=\"180\" font-weight=\"500\" fill=\"#e6dfd0\">象</text>"}]}]};
